package com.trampolim.api.education;

import java.security.SecureRandom;
import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class LearningPerformanceService {
    private final JdbcTemplate jdbc;private final LearningAccess access;private final AssessmentService assessments;
    public LearningPerformanceService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,AssessmentService assessments){this.jdbc=jdbc;this.access=access;this.assessments=assessments;}
    public Map<String,Object> dashboard(String email){
        long student=access.account(email).id();var courses=jdbc.queryForList("SELECT c.id,c.title FROM learning_courses c JOIN student_users u ON u.id=c.teacher_id WHERE c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND u.account_status='ACTIVE' AND (EXISTS(SELECT 1 FROM learning_lesson_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id WHERE p.student_id=? AND s.course_id=c.id) OR EXISTS(SELECT 1 FROM learning_assessment_attempts t JOIN learning_assessments a ON a.id=t.assessment_id WHERE t.student_id=? AND a.course_id=c.id)) ORDER BY c.id DESC LIMIT 200",student,student);
        long completedCourses=0,completedLessons=0,completedModules=0;
        // Queries operate only on the student's started courses. No classmate results are included.
        if(!courses.isEmpty()){
            String placeholders=String.join(",",Collections.nCopies(courses.size(),"?"));var args=new ArrayList<Object>();args.add(student);courses.forEach(course->args.add(course.get("id")));
            var lessons=jdbc.queryForList("SELECT s.course_id,m.id AS module_id,l.id,p.completed_at FROM learning_lessons l JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id LEFT JOIN learning_lesson_progress p ON p.lesson_id=l.id AND p.student_id=? WHERE l.status='PUBLISHED' AND l.validation_status='READY' AND s.course_id IN ("+placeholders+")",args.toArray());
            var required=jdbc.queryForList("SELECT a.id,a.course_id,a.module_id,EXISTS(SELECT 1 FROM learning_assessment_attempts t WHERE t.assessment_id=a.id AND t.student_id=? AND t.passed=TRUE) AS passed FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id WHERE a.status='PUBLISHED' AND (v.definition->>'requiredForCompletion')::boolean=TRUE AND a.course_id IN ("+placeholders+")",args.toArray());
            for(var course:courses){long id=((Number)course.get("id")).longValue();var rows=lessons.stream().filter(row->((Number)row.get("course_id")).longValue()==id).toList();long done=rows.stream().filter(row->row.get("completed_at")!=null).count();var tests=required.stream().filter(row->((Number)row.get("course_id")).longValue()==id).toList();boolean passed=tests.stream().allMatch(row->Boolean.TRUE.equals(row.get("passed")));var modules=new HashSet<Long>();rows.forEach(row->modules.add(((Number)row.get("module_id")).longValue()));long modulesDone=modules.stream().filter(module->rows.stream().filter(row->((Number)row.get("module_id")).longValue()==module).allMatch(row->row.get("completed_at")!=null)&&tests.stream().filter(row->row.get("module_id")!=null&&((Number)row.get("module_id")).longValue()==module).allMatch(row->Boolean.TRUE.equals(row.get("passed")))).count();boolean complete=!rows.isEmpty()&&done==rows.size()&&passed;if(complete)completedCourses++;completedLessons+=done;completedModules+=modulesDone;course.put("lessonsTotal",rows.size());course.put("lessonsCompleted",done);course.put("modulesTotal",modules.size());course.put("modulesCompleted",modulesDone);course.put("requiredAssessments",tests.size());course.put("passedRequiredAssessments",tests.stream().filter(row->Boolean.TRUE.equals(row.get("passed"))).count());course.put("progressPercent",rows.isEmpty()?0:Math.round(100d*done/rows.size()));course.put("completed",complete);}
        }
        long submitted=jdbc.queryForObject("SELECT count(*) FROM learning_assessment_attempts WHERE student_id=? AND status='SUBMITTED'",Long.class,student);long passed=jdbc.queryForObject("SELECT count(*) FROM learning_assessment_attempts WHERE student_id=? AND passed=TRUE",Long.class,student);long awards=jdbc.queryForObject("SELECT count(*) FROM learning_competency_awards WHERE student_id=?",Long.class,student);
        return Map.of("courses",courses,"coursesStarted",courses.size(),"coursesCompleted",completedCourses,"lessonsCompleted",completedLessons,"modulesCompleted",completedModules,"assessmentsSubmitted",submitted,"assessmentsPassed",passed,"competenciesEarned",awards);
    }
    public List<Map<String,Object>> competencies(String email){return jdbc.queryForList("SELECT "+awardFields()+",issuer_name,valid_until,revoked_at,skill_code,skill_level,highlighted,sort_order,share_expires_at,(share_hash IS NOT NULL AND share_expires_at>CURRENT_TIMESTAMP) AS sharing_active FROM learning_competency_awards WHERE student_id=? ORDER BY highlighted DESC,sort_order,awarded_at DESC LIMIT 500",access.account(email).id());}
    @Transactional("capacitaTransactionManager")public void present(String email,UUID id,AssessmentService.Presentation input){long user=access.account(email).id();if(input==null||input.sortOrder()<0||input.sortOrder()>10000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Ordem inválida.");if(jdbc.update("UPDATE learning_competency_awards SET highlighted=?,sort_order=? WHERE id=? AND student_id=?",input.highlighted(),input.sortOrder(),id,user)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Competência não conquistada nesta conta.");assessments.audit(user,null,id,"PRESENTATION_UPDATED");}
    @Transactional("capacitaTransactionManager")public Map<String,Object> share(String email,UUID id,boolean consent){long user=access.account(email).id();if(!consent)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Confirme o compartilhamento dos dados desta conquista.");byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);if(jdbc.update("UPDATE learning_competency_awards SET share_hash=?,share_expires_at=CURRENT_TIMESTAMP+INTERVAL '30 days',share_consent_at=CURRENT_TIMESTAMP WHERE id=? AND student_id=? AND revoked_at IS NULL AND (valid_until IS NULL OR valid_until>CURRENT_TIMESTAMP)",AssessmentService.hash(token),id,user)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);assessments.audit(user,null,id,"SHARE_CONSENTED");return Map.of("token",token,"expiresInDays",30);}
    @Transactional("capacitaTransactionManager")public void revoke(String email,UUID id){long user=access.account(email).id();if(jdbc.update("UPDATE learning_competency_awards SET share_hash=NULL,share_expires_at=NULL WHERE id=? AND student_id=?",id,user)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);assessments.audit(user,null,id,"SHARE_REVOKED");}
    public Map<String,Object> shared(String token){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.NOT_FOUND);var rows=jdbc.queryForList("SELECT "+Arrays.stream(awardFields().split(",")).map(field->"a."+field).reduce((a,b)->a+","+b).orElseThrow()+" FROM learning_competency_awards a JOIN student_users u ON u.id=a.student_id WHERE a.share_hash=? AND a.share_expires_at>CURRENT_TIMESTAMP AND u.account_status='ACTIVE' AND u.email_verified=TRUE AND a.revoked_at IS NULL AND (a.valid_until IS NULL OR a.valid_until>CURRENT_TIMESTAMP)",AssessmentService.hash(token));if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Compartilhamento indisponível, expirado ou revogado.");var result=rows.get(0);result.put("recordType","VERIFIED_LEARNING_COMPETENCY");result.put("formalCertificate",false);return result;}
    @Transactional("capacitaTransactionManager")public Map<String,Object> export(String email,boolean consent){long user=access.account(email).id();if(!consent)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Confirme a exportação das competências destacadas.");var rows=jdbc.queryForList("SELECT "+awardFields()+" FROM learning_competency_awards WHERE student_id=? AND highlighted=TRUE AND revoked_at IS NULL AND (valid_until IS NULL OR valid_until>CURRENT_TIMESTAMP) ORDER BY sort_order,awarded_at DESC",user);assessments.audit(user,null,null,"EXPORT_CONSENTED");return Map.of("schemaVersion",1,"trail","capacita","exportedAt",Instant.now().toString(),"competencies",rows,"formalCertificate",false);}
    private static String awardFields(){return "id,name,description,course_title,module_title,teacher_name,score_percent,criterion,awarded_at";}
}
